local({
  m <- as.numeric(as.character(migrant_landmutter))
  v <- as.numeric(as.character(migrant_landvater))
  g <- as.numeric(as.character(migrant_geborenindeutschland))
  case_when(
    m %in% 1 | v %in% 1 ~ "Non-minority",
    ((m %in% 2 & v %in% 2) | (m %in% 2 & !v %in% 1:2) | (v %in% 2 & !m %in% 1:2)) & g %in% 1:2 ~ "Minority",
    .default = "Unknown"
  )
})

local({
  s <- as.numeric(ses_score)
  case_when(
    is.na(s) ~ "Unknown",
    s <= stats::quantile(s, 0.4, na.rm = TRUE) ~ "Low",
    s <= stats::quantile(s, 0.6, na.rm = TRUE) ~ "Medium",
    .default = "High"
  )
})
